import { defineConfig } from 'astro/config';

// Production site: https://visafreely.com/ (GitHub Pages + custom domain)
// Sitemaps are generated by scripts/gen-sitemaps.mjs (segmented: core hubs
// vs pair pages, pair <lastmod> = verified date) as part of `npm run build`.
//
// i18n: Astro's built-in routing is declarative here — English lives at
// unprefixed paths, every other locale under /<locale>/. Which locales
// actually have pages is governed by src/i18n/launched.json (the page
// files under src/pages/<locale>/ exist only for launched locales);
// message copy is compiled from messages/<locale>.json by Paraglide
// (a step in `npm run build`).
export default defineConfig({
  site: 'https://visafreely.com',
  base: '/',
  trailingSlash: 'always',
  integrations: [],
  i18n: {
    defaultLocale: 'en',
    locales: ['en', 'zh-hans', 'zh-hant', 'ja', 'ko', 'th'],
    routing: {
      prefixDefaultLocale: false,
      redirectToDefaultLocale: false,
    },
  },
});
